svg.script:
(function () {
  var svg = document.documentElement;
  var semi = svg.getElementById('semi');
  var ball = svg.getElementById('ball');
  if (!semi || !ball) return;

  // Geometry (matches the drawn semicircle)
  var CX = 545;
  var CY = 285;
  var R = 255;
  var r = 72;
  var D_MAX = 145; // how far the ball can travel before the rim catches it

  // Ball physics
  var g = 1800;
  var friction = 2.1;
  var rimStiffness = 90;
  var rimDamping = 8;
  var bounce = 0.28;

  // Seesaw motor
  var theta = 0;
  var omega = 0;
  var maxTheta = (22 * Math.PI) / 180;
  var maxOmega = (65 * Math.PI) / 180;
  var motorAccel = 3.2;

  // Drive ball to centre (d = 0), then rest flat
  var Kp = 0.018;
  var Kd = 0.007;

  var d = 0;
  var v = 0;

  var PHASE_BALANCE = 'balance';
  var PHASE_PAUSE = 'pause';
  var PHASE_TIP = 'tip';
  var phase = PHASE_TIP;
  var phaseT = 0;
  var pauseFor = 1.8;
  var tipFor = 0.75;
  var tipSign = 1;
  var tipAngle = (17 * Math.PI) / 180;
  var balancedTime = 0;
  var balanceHold = 0.7;

  var reduce = false;
  try {
    reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch (e) {}

  function clamp(x, a, b) {
    return Math.max(a, Math.min(b, x));
  }

  function paint() {
    var deg = (theta * 180) / Math.PI;
    semi.setAttribute('transform', 'rotate(' + deg + ' ' + CX + ' ' + CY + ')');
    var c = Math.cos(theta);
    var s = Math.sin(theta);
    var px = CX + d * c + r * s;
    var py = CY + d * s + r * -c;
    // No-slip: φ = s / r with s = d along the edge. SVG +angle is clockwise.
    var rollDeg = (d / r) * (180 / Math.PI);
    ball.setAttribute(
      'transform',
      'translate(' + px + ' ' + py + ') rotate(' + (deg + rollDeg) + ')'
    );
  }

  function settleScore() {
    var dN = clamp(1 - Math.abs(d) / 40, 0, 1);
    var vN = clamp(1 - Math.abs(v) / 80, 0, 1);
    return dN * vN;
  }

  function targetTheta() {
    if (phase === PHASE_PAUSE) return 0;
    if (phase === PHASE_TIP) return tipSign * tipAngle;
    var catchCmd = clamp(-Kp * d - Kd * v, -maxTheta, maxTheta);
    var flatBlend = settleScore();
    return catchCmd * (1 - flatBlend * 0.92);
  }

  function isSettled() {
    return (
      Math.abs(d) < 5 &&
      Math.abs(v) < 14 &&
      Math.abs(theta) < 0.025 &&
      Math.abs(omega) < 0.08
    );
  }

  function step(dt) {
    phaseT += dt;

    if (phase === PHASE_TIP && phaseT >= tipFor) {
      phase = PHASE_BALANCE;
      phaseT = 0;
      balancedTime = 0;
    } else if (phase === PHASE_BALANCE) {
      if (isSettled()) {
        balancedTime += dt;
        if (balancedTime >= balanceHold) {
          phase = PHASE_PAUSE;
          phaseT = 0;
          tipSign *= -1;
          theta = 0;
          omega = 0;
          d = 0;
          v = 0;
        }
      } else {
        balancedTime = 0;
      }
    } else if (phase === PHASE_PAUSE && phaseT >= pauseFor) {
      phase = PHASE_TIP;
      phaseT = 0;
    }

    if (phase === PHASE_PAUSE) {
      theta = 0;
      omega = 0;
      d = 0;
      v = 0;
      paint();
      return;
    }

    var desired = targetTheta();
    var wantOmega = clamp((desired - theta) * 5.2, -maxOmega, maxOmega);
    omega += clamp((wantOmega - omega) * 7 * dt, -motorAccel * 20 * dt, motorAccel * 20 * dt);
    omega = clamp(omega, -maxOmega, maxOmega);
    theta += omega * dt;
    theta = clamp(theta, -maxTheta, maxTheta);

    var a = g * Math.sin(theta) - friction * v;
    if (Math.abs(theta) < 0.08) {
      a += -9.5 * d - 5.5 * v;
    }

    if (d > D_MAX - 18) {
      var over = d - (D_MAX - 18);
      a -= rimStiffness * over + rimDamping * Math.max(0, v);
    }
    if (d < -D_MAX + 18) {
      var overL = -D_MAX + 18 - d;
      a += rimStiffness * overL + rimDamping * Math.max(0, -v);
    }

    v += a * dt;
    d += v * dt;

    if (d > D_MAX) {
      d = D_MAX;
      if (v > 0) v = -v * bounce;
    } else if (d < -D_MAX) {
      d = -D_MAX;
      if (v < 0) v = -v * bounce;
    }

    paint();
  }

  paint();
  if (reduce) return;

  var last = performance.now();
  function frame(now) {
    var dt = Math.min(0.033, (now - last) / 1000);
    last = now;
    // fixed substeps for stability
    var steps = 2;
    var h = dt / steps;
    for (var i = 0; i < steps; i++) step(h);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
